// @ts-nocheck
// Site Intelligence Report (+ optional §9 Concept Plan Review)
//
// This is a skeleton. Sections marked {{...}} are placeholders to fill from the
// synthesis + research outputs. The §9 block is wrapped in a conditional —
// include it only when a concept plan was provided.
//
// Render with: noetic-pdf/src/render-cli.tsx <this-file> <output.pdf>

import * as React from '{{REACT_IMPORT}}';
import {
  NoeticDocument,
  CoverPage,
  ContentsPage,
  NoeticPage,
  MarkdownBody,
  KeyValue,
  Divider,
  SectionHeading,
  SubHeading,
  SeverityBadge,
  Callout,
  Table,
  Badge,
} from '{{NOETIC_PDF_INDEX}}';

// Set this from the orchestrator: true when a concept plan was provided.
const HAS_CONCEPT_PLAN = {{HAS_CONCEPT_PLAN}}; // true | false

const REPORT_TITLE = HAS_CONCEPT_PLAN
  ? 'Site Intelligence Report & Concept Plan Review'
  : 'Site Intelligence Report';

function Report() {
  return (
    <NoeticDocument title={`${REPORT_TITLE} — {{PROPERTY_LABEL}}`}>
      {/* ── Cover page (title sheet only — no children) ─ */}
      <CoverPage
        title={REPORT_TITLE}
        subtitle="{{PROPERTY_ADDRESS}}"
        date="{{REPORT_DATE}}"
      />

      {/* ── Contents page: metadata + TOC ONLY ──────────
          Do NOT place §1 content here. Overflowing children
          slam into the fixed logo header on continuation pages. */}
      <ContentsPage
        title={REPORT_TITLE}
        metadata={[
          { label: 'Property', value: '{{PROPERTY_ADDRESS}}' },
          { label: 'Legal', value: '{{LEGAL_DESCRIPTION}}' },
          { label: 'Acreage', value: '{{ACREAGE}}' },
          { label: 'Owner', value: '{{OWNER}}' },
          { label: 'Parcel ID', value: '{{PARCEL_ID}}' },
          { label: 'Zoning', value: '{{ZONING_SUMMARY}}' },
          { label: 'Jurisdiction', value: '{{JURISDICTION_SUMMARY}}' },
          { label: 'Proposed Use', value: '{{INTENDED_USE}}' },
          { label: 'Report Date', value: '{{REPORT_DATE}}' },
          { label: 'Prepared by', value: 'Noetic' },
        ]}
        tocItems={[
          '1. Executive Summary',
          '2. Property Identity',
          '3. Jurisdiction & Regulatory Framework',
          '4. Chain of Title & Recorded Instruments',
          '5. Environmental Constraints',
          '6. Infrastructure & Utilities',
          '7. Programs & Opportunities',
          '8. Discipline Findings',
          ...(HAS_CONCEPT_PLAN ? ['9. Concept Plan Review'] : []),
          HAS_CONCEPT_PLAN ? '10. Recommendations & Open Questions' : '9. Considerations Before Concept Design',
        ]}
      />

      {/* ── 1. Executive Summary (its own page) ────────── */}
      <NoeticPage>
        <SectionHeading number={1}>Executive Summary</SectionHeading>
        {/* {{EXECUTIVE_SUMMARY_BULLETS}}
            3-5 bullets: go/no-go signal, top 3 risks, top 3 opportunities. */}
      </NoeticPage>

      {/* ── 2. Property Identity ──────────────────────── */}
      <NoeticPage>
        <SectionHeading number="2">Property Identity</SectionHeading>
        {/* Address, parcels, owner, legal description, area, deed history table */}
        <Table
          headerStyle="dark"
          columns={[
            { key: 'field', label: 'Field' },
            { key: 'value', label: 'Value' },
            { key: 'source', label: 'Source' },
          ]}
          rows={[
            // {{PROPERTY_IDENTITY_ROWS}}
          ]}
        />
      </NoeticPage>

      {/* ── 3. Jurisdiction & Regulatory Framework ────── */}
      <NoeticPage>
        <SectionHeading number="3">Jurisdiction & Regulatory Framework</SectionHeading>
        {/* {{JURISDICTION_NARRATIVE}}
            Includes: city/ETJ/county determination, base zoning, overlays,
            adopted plans, ASMP/MTP street level if applicable. */}

        {/* MANDATORY SUBHEADING — required on every diligence run. If no active
            permits or case history are on record, say so explicitly. Do not omit. */}
        <SubHeading>Active permits & case history</SubHeading>
        {/* {{ACTIVE_PERMITS_NARRATIVE}}
            Cover: active site development permits, building permits, plat-amendment
            applications, variances, or other open cases on this parcel and the
            controlling plat. List adjacent pads' permit status if relevant to
            this pad's path. If none of record, state "No active permits or case
            history on record" and identify the pre-application meeting contact. */}
      </NoeticPage>

      {/* ── 4. Chain of Title & Recorded Instruments ──── */}
      <NoeticPage>
        <SectionHeading number="4">Chain of Title & Recorded Instruments</SectionHeading>
        <Table
          headerStyle="dark"
          columns={[
            { key: 'instrument', label: 'Instrument' },
            { key: 'type', label: 'Type' },
            { key: 'filed', label: 'Filed' },
            { key: 'burdens', label: 'Burdens this parcel?' },
          ]}
          rows={[
            // {{CHAIN_OF_TITLE_ROWS}}
          ]}
        />
        {/* {{INSTRUMENT_PROVISIONS_NARRATIVE}} */}
      </NoeticPage>

      {/* ── 5. Environmental Constraints ──────────────── */}
      <NoeticPage>
        <SectionHeading number="5">Environmental Constraints</SectionHeading>
        {/* Watershed, floodplain, CEFs, heritage trees, aquifer recharge.
            Use SeverityBadge per constraint. */}
      </NoeticPage>

      {/* ── 6. Infrastructure & Utilities ─────────────── */}
      <NoeticPage>
        <SectionHeading number="6">Infrastructure & Utilities</SectionHeading>
        {/* Water, wastewater, drainage, transportation, ROW. */}
      </NoeticPage>

      {/* ── 7. Programs & Opportunities ───────────────── */}
      <NoeticPage>
        <SectionHeading number="7">Programs & Opportunities</SectionHeading>
        {/* Per-program <Callout variant="insight"> with eligibility status. */}
      </NoeticPage>

      {/* ── 8. Discipline Findings — overview page ────── */}
      {/* MANDATORY: a constraint-matrix summary page MUST appear before the
          per-discipline detail pages. It gives an exec reader the consolidated
          risk view at a glance without paging through ten discipline sub-sections. */}
      {/* The "Discipline" column uses the SHORT label from
          references/phase3-disciplines.md (Zoning, Site, Stormwater,
          Floodplain, Env, Trees, Transport, Water, Fire, Parkland).
          NEVER use bare slugs (zlu, sde, etc.) — those are internal. */}
      <NoeticPage>
        <SectionHeading number="8">Discipline Findings</SectionHeading>
        <SubHeading>Constraint matrix</SubHeading>
        <MarkdownBody markdown={`The table below consolidates the significant and moderate findings across all ten disciplines. Detail and citations follow in 8.1-8.10.`} />
        <Table
          headerStyle="dark"
          columns={[
            { header: 'Discipline', width: 90, bold: true },
            { header: 'Topic', width: 200 },
            { header: 'Level', width: 80 },
            { header: 'Citation', flex: 1 },
          ]}
          rows={[
            // {{CONSTRAINT_MATRIX_ROWS}}
            // Pull every significant + moderate + opportunity row from
            // synthesis/issue-matrix.md. Skip pure `note` rows unless
            // they're worth surfacing at exec level. Keep to one page.
            //
            // For "Discipline" column, use the short label from
            // references/phase3-disciplines.md:
            //   Zoning, Site, Stormwater, Floodplain, Env, Trees, Transport,
            //   Water, Fire, Parkland
          ]}
        />
      </NoeticPage>

      {/* ── 8.1-8.10 per-discipline detail pages ──────── */}
      {/* SubHeading uses the FULL display label from
          references/phase3-disciplines.md. NEVER include the slug in
          parentheses (e.g., "Zoning & Land Use (zlu)" is wrong;
          just "Zoning & Land Use"). Cross-references in body text
          should also use the friendly label ("see Floodplain",
          "cross to Stormwater"), NOT the slug. */}
      {[
        { slug: 'zlu',  label: 'Zoning & Land Use' },
        { slug: 'sduf', label: 'Site Plan & Form' },
        { slug: 'sde',  label: 'Stormwater & Drainage' },
        { slug: 'fwp',  label: 'Floodplain' },
        { slug: 'el',   label: 'Environmental' },
        { slug: 'eptp', label: 'Tree Protection & Erosion Control' },
        { slug: 'ta',   label: 'Transportation' },
        { slug: 'wwp',  label: 'Water & Wastewater' },
        { slug: 'fire', label: 'Fire' },
        { slug: 'park', label: 'Parkland' },
      ].map((d, i) => (
        <NoeticPage key={d.slug}>
          <SubHeading>{`8.${i + 1} ${d.label}`}</SubHeading>
          {/* {{DISCIPLINE_FINDINGS_FOR_SLUG[d.slug]}} */}
        </NoeticPage>
      ))}

      {/* ── 9. Concept Plan Review (only if concept plan provided) ─── */}
      {HAS_CONCEPT_PLAN && (
        <>
          <NoeticPage>
            <SectionHeading number="9">Concept Plan Review</SectionHeading>
            <SubHeading number="9.1">Plan Summary</SubHeading>
            {/* {{PLAN_SUMMARY_FROM_PHASE1}}
                Drawing-derived facts: building dimensions, site coverage,
                parking, drainage, design vehicle. */}
            <Table
              headerStyle="light"
              columns={[
                { key: 'field', label: 'Field' },
                { key: 'value', label: 'Value' },
                { key: 'source', label: 'Source' },
              ]}
              rows={[
                // {{PLAN_SUMMARY_ROWS}}
              ]}
            />
          </NoeticPage>

          {/* MANDATORY 9.2 — measured-from-scale setbacks. Phase 1 vision
              extracts these; the SIR must expose the labeled-vs-measured
              comparison so the engineer can verify their drawing reads true.
              Do NOT skip this subsection even if all setbacks comply. */}
          <NoeticPage>
            <SubHeading number="9.2">Measured setbacks (read from scale)</SubHeading>
            {/* {{MEASURED_SETBACKS_NARRATIVE}}
                State the published scale. For each property edge, show:
                jurisdictional minimum, CSP-labeled dimension, measured dimension
                from the published scale, compliance margin. Use a Table. */}
            <Table
              headerStyle="dark"
              columns={[
                { header: 'Edge', width: 80, bold: true },
                { header: 'Code minimum', width: 110 },
                { header: 'CSP labeled', width: 110 },
                { header: 'Measured (building face)', width: 140 },
                { header: 'Compliance', flex: 1 },
              ]}
              rows={[
                // {{MEASURED_SETBACKS_ROWS}}
              ]}
            />
          </NoeticPage>

          {/* MANDATORY 9.3 — independent IC computation. The CSP usually
              labels building footprint and parking-stall count, but rarely
              states a total IC %. Compute from the labeled / scaled areas
              and surface the result. Flag as data-gap if the engineer
              should produce a measured value on the next CSP revision. */}
          <NoeticPage>
            <SubHeading number="9.3">Impervious cover verification</SubHeading>
            {/* {{IC_VERIFICATION_NARRATIVE}}
                Break IC into surfaces: building footprint, parking,
                drive aisles, sidewalks, service pads. Show area (SF) and
                % of lot for each. Subtotal the impervious. Compare against
                any jurisdictional IC limit. If the CSP doesn't provide a
                measured IC, flag with a Callout variant="data-gap" and
                state the recommended next CSP revision. */}
            <Table
              headerStyle="light"
              columns={[
                { header: 'Surface', width: 200, bold: true },
                { header: 'Area (SF)', width: 110 },
                { header: '% of lot', width: 90 },
                { header: 'Source', flex: 1 },
              ]}
              rows={[
                // {{IC_VERIFICATION_ROWS}}
              ]}
            />
          </NoeticPage>

          <NoeticPage>
            <SubHeading number="9.4">Compliance Check</SubHeading>
            {/* For every significant/moderate constraint from §5–§8:
                  does the plan address it? Use a Table where each row is
                  a constraint with Plan response + Level. */}
          </NoeticPage>

          <NoeticPage>
            <SubHeading number="9.5">Discipline Plan-Specific Findings</SubHeading>
            {/* From the "Plan-specific findings" blocks in each Phase 3 output. */}
          </NoeticPage>

          <NoeticPage>
            <SubHeading number="9.6">Findings that differ from CSP / cover-sheet assumptions</SubHeading>
            {/* Use Callout variant="correction" for each material discrepancy
                between the plan title block and verified facts. */}
          </NoeticPage>

          <NoeticPage>
            <SubHeading number="9.7">Open Questions for the Engineer</SubHeading>
            {/* Bulleted list with page references. */}
          </NoeticPage>
        </>
      )}

      {/* ── 10 / 9. Recommendations & Open Questions ──── */}
      <NoeticPage>
        <SectionHeading number={HAS_CONCEPT_PLAN ? '10' : '9'}>
          {HAS_CONCEPT_PLAN
            ? 'Recommendations & Open Questions'
            : 'Considerations Before Concept Design'}
        </SectionHeading>

        {/* MANDATORY SUBHEADING — required on every diligence run. Surfaces
            every data-gap from the issue-matrix as a single actionable table
            (Gap / Action / Owner / Timeline). The reader should never have to
            page through the report to assemble the punch list. */}
        <SubHeading>Data gaps requiring action</SubHeading>
        {/* {{DATA_GAPS_NARRATIVE}}
            One sentence framing the table that follows. */}
        <Table
          headerStyle="dark"
          columns={[
            { header: 'Gap', width: 180, bold: true },
            { header: 'Action / source', flex: 1 },
            { header: 'Owner', width: 150 },
          ]}
          rows={[
            // {{DATA_GAPS_ROWS}}
            // Every data-gap and Bucket-B item from synthesis/issue-matrix.md
            // becomes a row here. Specific owner (engineer, counsel, title
            // company, lender, surveyor, etc.).
            //
            // DO NOT add a "Timeline" column. The skill does not produce
            // schedule estimates — see the no-timeline rule in
            // references/deliverables.md.
          ]}
        />

        <SubHeading>What to do next, in priority order</SubHeading>
        {/* {{RECOMMENDATIONS_PRIORITY_NARRATIVE}}
            Sequenced action list, grouped by week or phase. */}
      </NoeticPage>
    </NoeticDocument>
  );
}

export default <Report />;
